INSERT INTO `tbl_documents` VALUES (22,'Mahesh 1',22,'<h2>Curriculum Vitae</h2><p>THE BASICS The curriculum vitae, also known as a CV or vita, is a comprehensive statement of your educational background, teaching, and research experience. It is the standard representation of credentials within academia.  The full CV is only used when applying for academic positions in four-year institutions. </p><p> Do not use a CV when applying to community colleges—use a teacher-focused résumé instead.  Tailor your CV to the specific positions to which you are applying and place more relevant sections earlier in the document. – For a position at a teaching-focused liberal arts college, the CV will strongly emphasize teaching. – For a position at a research-intensive university, the CV will accentuate research.  Format can vary by field, so also seek disciplinary-specific advice from advisers, professors, and others within your field. </p><ol><li><p> There are no length restrictions for CVs.</p></li></ol>',NULL,'2024-12-23 23:12:12',22,'Share'),(23,'Ganesh 2',21,'<h2>Testing 2</h2><table><thead><tr><th><p>T 1</p></th><th><p>T2</p></th><th><p>T3</p></th><th><p>T4</p></th><th><p>T5</p></th><th><p>T6</p></th></tr></thead><tbody><tr><td><p>1111</p></td><td><p>2222</p></td><td><p>3333</p></td><td><p>4444</p></td><td><p>5555</p></td><td><p>6666</p></td></tr></tbody></table><h5><strong>ssdg</strong></h5><p>sdggsd</p><p><br></p><p><br></p><p>sdgsedgd<img src=\"data:image/png;base64,\" contenteditable=\"false\"><br></p>',NULL,'2025-01-17 08:30:38',21,'Share'),(24,'Mahesh 2',22,'<p>Analyn Ocampo Davis, CA 95616 | (559) 555-5683 Email: aocampo@ucdavis.edu OBJECTIVE Work study eligible undergraduate student seeking an on-campus job opportunity. EDUCATION Intended Major: Communication, Bachelor of Arts Degree University of California, Davis Expected Graduation: June 2027 RELATED COURSEWORK Beginning Composition, Precalculus, Freshman Seminar: Ethnographic Performance, General Psychology, Children in the Garden (Enrolled Spring 2024) SKILLS Computer: Intermediate in Word, use of Internet search engines, Outlook and email in both PC and Mac platforms Language: Fluent in spoken Tagalog (minimal written ability) EXPERIENCE Receptionist, T &amp; T Electronics, Sanger, CA June 2023 - August 2023 ● Created a welcoming atmosphere for mid-sized manufacturing firm. ● Managed Outlook calendars and schedules of four full-time sales staff, using effective communication skills. ● Organized and cleaned office to create efficient workspace and professional appearance. ● Ensured packages were mailed in a timely manner using the most cost effective carrier for the transaction. Child Care Provider, Self Employed, Sanger, CA June 2021 - September 2023 ● Provided safe, reliable care for children (infant to12 years) in their homes. ● Effectively adapted communication style and planned activities to meet the developmental needs of children and create a positive experience. ● Partnered with parents to ensure consistency and clear boundaries with children. ● Built positive rapport and reputation for reliability, resulting in extensive referrals. ACTIVITIES ● Member, UC Davis Intramural Volleyball September 2023 - Present ● Member, Sanger High School Marching Band August 2019 - June 2023</p>',NULL,'2024-12-23 23:12:12',22,'Share'),(39,'react-to-pdf',21,'<p>import generatePDF, { Options } from \"react-to-pdf\";</p><p>import { Card } from \"./Card\";</p><p>import { Button } from \"./Button\";</p><p>import { Container } from \"./Container\";</p><p><br></p><p>const options: Options = {</p><p>&nbsp; filename: \"using-function.pdf\",</p><p>&nbsp; page: {</p><p>&nbsp; &nbsp; margin: 20</p><p>&nbsp; }</p><p>};</p><p><br></p><p>const getTargetElement = () =&gt; document.getElementById(\"container\");</p><p><br></p><p>const downloadPdf = () =&gt; generatePDF(getTargetElement, options);</p><p><br></p><p>const App = () =&gt; {</p><p>&nbsp; return (</p><p>&nbsp; &nbsp; &lt;Container&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;Button onClick={downloadPdf}&gt;Download PDF&lt;/Button&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;div id=\"container\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;Card imageId={20} title=\"Using function example\" /&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;/div&gt;</p><p>&nbsp; &nbsp; &lt;/Container&gt;</p><p>&nbsp; );</p><p>};</p><p><br></p><p>export default App;</p><p><br></p>','2025-01-17 08:30:38','2025-01-17 10:04:28',1,'0'),(40,'UI Basics and Hands On',21,'<p><strong>Project Based Learning:</strong></p><p>Try to use Brave Browser for learning.</p><p>&nbsp;</p><p><strong>HTML:</strong></p><p>Video tutorial : <a href=\"https://www.youtube.com/watch?v=qz0aGYrrlhU\">HTML Tutorial for Beginners: HTML Crash Course</a>&nbsp;</p><p>Documentation tutorials: <a href=\"https://www.w3schools.com/html/default.asp\">W3Schools.com</a> &nbsp;-Learn Up to API’s.</p><p>Practice Makes you perfect don’t skip it: <a href=\"https://www.w3schools.com/html/exercise.asp?filename=exercise_html_attributes1\">W3Schools HTML Exercise</a>&nbsp;</p><p>&nbsp;</p><p><strong>CSS:&nbsp;</strong></p><p>Video tutorial: <a href=\"https://www.youtube.com/watch?v=1Rs2ND1ryYc&amp;amp;amp;amp;amp;t=85s\">CSS Tutorial - Zero to Hero (Complete Course)</a>&nbsp;</p><p>Documentation tutorials: <a href=\"https://www.w3schools.com/css/default.asp\">W3Schools.com</a> &nbsp;- Learn Up to CSS advanced.</p><p>I am saying it again Practice Makes you perfect don’t skip it: <a href=\"https://www.w3schools.com/css/exercise.asp?filename=exercise_selectors1\">W3Schools CSS Exercise</a></p><p>&nbsp;</p><p><strong>Java Script:</strong></p><p>This is not one day thing please go slow and consistent :&nbsp;</p><p>Video tutorial: <a href=\"https://www.youtube.com/playlist?list=PLsyeobzWxl7rrvgG7MLNIMSTzVCDZZcT4\">JavaScript Tutorial for Beginners</a>&nbsp;</p><p>Course: <a href=\"https://www.udemy.com/course/javascriptfundamentals/\">Free JavaScript Tutorial - JavaScript Fundamentals</a> &nbsp;- mandatory</p><p>Document tutorial : <a href=\"https://www.w3schools.com/js/default.asp\">W3Schools.com</a></p><p>&nbsp;</p><p><strong>JQuery:</strong></p><p>It is JavaScript Library, Makes you life easier writing JS just learn some basicsDocument tutorial : <a href=\"https://www.w3schools.com/jquery/\">W3Schools.com</a></p><p>&nbsp;</p><p>&nbsp; <strong>Bootstrap 3:</strong></p><p>&nbsp;Don’t fall for BS4 and 5 the projects your going to Work they are runs with BS3.4.7, please stick with BS3 Upto you got clear idea.</p><p>Course: <a href=\"https://www.udemy.com/course/introduction-to-bootstrap-3/\">Free Bootstrap Tutorial - Introduction to Bootstrap 3</a>&nbsp;</p><p>Document tutorial : <a href=\"https://www.w3schools.com/bootstrap/default.asp\">W3Schools.com</a>&nbsp;</p><p>Video tutorial: <a href=\"https://www.youtube.com/playlist?list=PL4cUxeGkcC9g_69kOfXICzT_hZ79_td99\">Bootstrap 3 Tutorials</a>&nbsp;</p><p>Do some Exercise:<a href=\"https://www.w3schools.com/bootstrap/exercise_bs3.asp?filename=exercise_bs3_tables1\">W3Schools BOOTSTRAP 3 Exercise</a>&nbsp;</p><p>&nbsp;</p><p><strong>LESS and SASS</strong>:&nbsp;</p><p>These are CSS pre-processors, these makes your life easy with CSS. As per our project requirement we are using LESS as a pre processor, so stick with LESS for now</p><p>Video : <a href=\"https://www.youtube.com/watch?v=YD91G8DdUsw&amp;amp;amp;amp;amp;t=471s\">Less CSS Pre-Processor Tutorial</a>&nbsp;</p><p>Documentation: <a href=\"https://www.tutorialspoint.com/less/index.htm\">LESS Tutorial</a> &nbsp;- just refer only Language Feature</p><p>Did you feel anything is missing!</p><p>I know, your looking for Practice URL, don’t worry on project everyday your going to use it.</p><p>&nbsp;</p><p><strong>JSTL:&nbsp;</strong></p><p><a href=\"https://www.javatpoint.com/jstl\">JSTL Tutorial and Examples - javatpoint</a> &nbsp;- Just Understand JSTL Core Tags those are sufficient for now now to work without confusion.</p><p>&nbsp;</p><p><strong>Project Structure:</strong></p><p>In the project we don’t use html files there we can use JSP and Tag files to re-use the elements.</p><p>If you see a Ecom Site, there are thousands of products we cant create a html file for each product, so things brings two new concepts here.</p><ol><li><p>Encapsulating Reusable Content</p></li><li><p>CMS (Contant Manage mentsystem)</p></li></ol><p>&nbsp;</p><p><strong>Encapsulating Reusable Content:</strong></p><p>&nbsp;</p><p>Assume this is a Html page you can break this page into peaces called tag files like header.tag footer.tag productinage.tag productdetails.tag like the way we brake that html page.</p><p>Take that yellow box as productlistitem.tag by using jstl condition you call that productlistitem.tag file multiple times.</p><p>The tag file creates html content multiple times but how it’s content change !!!!</p><p>There the CMS came into picture.</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>CMS (Contant Manage mentsystem):</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>It will change the View page contents based on the page and product that you are accessing.If you want to learn more about this please go through the documentation: <a href=\"https://omnireach-workspace.slack.com/files/U02E63J1RGQ/F03N30K6J5S/cmsandemail.pdf\">https://omnireach-workspace.slack.com/files/U02E63J1RGQ/F03N30K6J5S/cmsandemail.pdf</a>Connect your Slack account</p>','2025-01-17 08:30:38','2025-01-20 05:48:02',1,'Share'),(41,'html2canvas',21,'<p>These are all of the available configuration options.</p><table><thead><tr><th><p>Name</p></th><th><p>Default</p></th><th><p>Description</p></th></tr></thead><tbody><tr><td><p>allowTaint</p></td><td><p><code>false</code></p></td><td><p>Whether to allow cross-origin images to taint the canvas</p></td></tr><tr><td><p>backgroundColor</p></td><td><p><code>#ffffff</code></p></td><td><p>Canvas background color, if none is specified in DOM. Set <code>null</code> for transparent</p></td></tr><tr><td><p>canvas</p></td><td><p><code>null</code></p></td><td><p>Existing <code>canvas</code> element to use as a base for drawing on</p></td></tr><tr><td><p>foreignObjectRendering</p></td><td><p><code>false</code></p></td><td><p>Whether to use ForeignObject rendering if the browser supports it</p></td></tr><tr><td><p>imageTimeout</p></td><td><p><code>15000</code></p></td><td><p>Timeout for loading an image (in milliseconds). Set to <code>0</code> to disable timeout.</p></td></tr><tr><td><p>ignoreElements</p></td><td><p><code>(element) =&gt; false</code></p></td><td><p>Predicate function which removes the matching elements from the render.</p></td></tr><tr><td><p>logging</p></td><td><p><code>true</code></p></td><td><p>Enable logging for debug purposes</p></td></tr><tr><td><p>onclone</p></td><td><p><code>null</code></p></td><td><p>Callback function which is called when the Document has been cloned for rendering, can be used to modify the contents that will be rendered without affecting the original source document.</p></td></tr><tr><td><p>proxy</p></td><td><p><code>null</code></p></td><td><p>Url to the <a href=\"https://html2canvas.hertzen.com/proxy/\">proxy</a> which is to be used for loading cross-origin images. If left empty, cross-origin images won’t be loaded.</p></td></tr><tr><td><p>removeContainer</p></td><td><p><code>true</code></p></td><td><p>Whether to cleanup the cloned DOM elements html2canvas creates temporarily</p></td></tr><tr><td><p>scale</p></td><td><p><code>window.devicePixelRatio</code></p></td><td><p>The scale to use for rendering. Defaults to the browsers device pixel ratio.</p></td></tr><tr><td><p>useCORS</p></td><td><p><code>false</code></p></td><td><p>Whether to attempt to load images from a server using CORS</p></td></tr><tr><td><p>width</p></td><td><p><code>Element</code> width</p></td><td><p>The width of the <code>canvas</code></p></td></tr><tr><td><p>height</p></td><td><p><code>Element</code> height</p></td><td><p>The height of the <code>canvas</code></p></td></tr><tr><td><p>x</p></td><td><p><code>Element</code> x-offset</p></td><td><p>Crop canvas x-coordinate</p></td></tr><tr><td><p>y</p></td><td><p><code>Element</code> y-offset</p></td><td><p>Crop canvas y-coordinate</p></td></tr><tr><td><p>scrollX</p></td><td><p><code>Element</code> scrollX</p></td><td><p>The x-scroll position to used when rendering element, (for example if the Element uses <code>position: fixed</code>)</p></td></tr><tr><td><p>scrollY</p></td><td><p><code>Element</code> scrollY</p></td><td><p>The y-scroll position to used when rendering element, (for example if the Element uses <code>position: fixed</code>)</p></td></tr><tr><td><p>windowWidth</p></td><td><p><code>Window.innerWidth</code></p></td><td><p>Window width to use when rendering <code>Element</code>, which may affect things like Media queries</p></td></tr><tr><td><p>windowHeight</p></td><td><p><code>Window.innerHeight</code></p></td><td><p>Window height to use when rendering <code>Element</code>, which may affect things like Media queries</p></td></tr></tbody></table><p>If you wish to exclude certain <code>Element</code>s from getting rendered, you can add a <code>data-html2canvas-ignore</code> attribute to those elements and html2canvas will exclude them from the rendering.</p>','2025-01-17 08:30:38','2025-01-17 08:30:38',1,'0'),(42,'google',21,'<h3><a href=\"https://stackoverflow.com/questions/5703441/mysql-error-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresp\">MySQL error: You have an error in your SQL syntax; check ...</a></h3><p><a href=\"https://stackoverflow.com/questions/5703441/mysql-error-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresp\"><span class=\"image-link\" contenteditable=\"false\"><img src=\"data:image/png;base64,\"></span></a><br></p><p><a href=\"https://stackoverflow.com/questions/5703441/mysql-error-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresp\">Stack Overflow</a></p><p><a href=\"https://stackoverflow.com/questions/5703441/mysql-error-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresp\">https://stackoverflow.com › questions › mysql-error-yo...</a></p><p><em>You have</em> an <em>error</em> in <em>your SQL syntax</em>; <em>check</em> the <em>manual</em> that <em>corresponds</em> to <em>your MySQL server version</em> for the <em>right syntax</em> to <em>use near</em> \' at <em>line</em> 3.</p><p><a href=\"https://stackoverflow.com/a/5703471\">6 answers</a>&nbsp;·&nbsp;Top answer:&nbsp;You have to change delimiter before using triggers, stored procedures and so on. delimiter ...</p><p><em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">You have</a></em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\"> an </a><em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">error</a></em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\"> in </a><em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">your SQL syntax</a></em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">; </a><em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">check</a></em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\"> the </a><em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\">manual</a></em><a href=\"https://stackoverflow.com/questions/11093634/you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-to-your\"> that ...</a></p><p>19 Jun 2012</p><p><em><a href=\"https://stackoverflow.com/questions/33484833/error-in-your-sql-syntax-near\">error</a></em><a href=\"https://stackoverflow.com/questions/33484833/error-in-your-sql-syntax-near\"> in </a><em><a href=\"https://stackoverflow.com/questions/33484833/error-in-your-sql-syntax-near\">your SQL syntax near</a></em><a href=\"https://stackoverflow.com/questions/33484833/error-in-your-sql-syntax-near\"> (?,?,?) - Stack Overflow</a></p><p>2 Nov 2015</p><p><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">#1064 -</a><em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">You have</a></em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\"> an </a><em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">error</a></em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\"> in </a><em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">your SQL syntax</a></em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">; </a><em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\">check</a></em><a href=\"https://stackoverflow.com/questions/21798464/1064-you-have-an-error-in-your-sql-syntax-check-the-manual-that-corresponds-t\"> the ...</a></p><p>15 Feb 2014</p><p><em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\">ERROR</a></em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\"> 1064 (42000): </a><em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\">You have</a></em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\"> an </a><em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\">error</a></em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\"> in </a><em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\">your SQL syntax</a></em><a href=\"https://stackoverflow.com/questions/36099028/error-1064-42000-you-have-an-error-in-your-sql-syntax-want-to-configure-a-pa\"> ...</a></p><p>19 Mar 2016</p><p><a href=\"https://www.google.com/search?q=You+have+an+error+in+your+SQL+syntax;+check+the+manual+that+corresponds+to+your+MySQL+server+version+for+the+right+syntax+to+use+near+%27re+thrilled+to+inform+you+that+you%27ve+been+assigned+a+new+course+as+part+of+your%27+at+line+1+site:stackoverflow.com&amp;amp;sca_esv=ec4e310bc6b52ebd&amp;amp;rlz=1C1RXQR_enIN1125IN1126&amp;amp;sxsrf=ADLYWIIRlFT2h1rlGZFqyYJEf8co8Na6Ww:1736934926378&amp;amp;sa=X&amp;amp;ved=2ahUKEwivmKPquveKAxXEr1YBHeK1Hi4QrQIoBHoECB4QBQ\">More results from stackoverflow.com</a></p>','2025-01-17 08:30:38','2025-01-17 08:30:38',1,'0'),(43,'SAP Commerce Setup for SPARTACUS',21,'<p><strong>HYBRIS 2205 WITH SAPARTACUS</strong></p><ol><li><p>Install JDK 17 -: <a href=\"https://www.oracle.com/java/technologies/javase/jdk17-archive-downloads.html\">https://www.oracle.com/java/technologies/javase/jdk17-archive-downloads.html</a></p></li><li><p>Download SAP Hybris Suite 2205 from URL -: <a href=\"https://omnireach2021-my.sharepoint.com/:u:/r/personal/mayank_rathi_omnireach_app/Documents/Desktop/CXCOMM220500P_17-80006942.ZIP?csf=1&amp;amp;amp;web=1&amp;amp;amp;e=RhVHt4\">CXCOMM220500P_17-80006942.ZIP</a></p></li><li><p>Create a folder HybrisSpartacus(Example) and extract the ZIP under this folder.</p></li><li><p>Download spartacussampledata.2105.zip -: <a href=\"https://github.com/SAP/spartacus/releases/download/storefront-4.1.0/spartacussampledata.2105.zip\">https://github.com/SAP/spartacus/releases/download/storefront-4.1.0/spartacussampledata.2105.zip</a></p></li><li><p>In hybris/bin folder create the folder custom and create spartacussampledata under custom folder.</p></li><li><p>Extract spartacussampledata.2105.zip in spartacussampledata folder.</p></li><li><p>Move the custom.properties file from spartacussampledata/resources/installer/customconfig to hybris-commerce-suite-2205/installer/customconfig</p></li><li><p>Download recipe from -: <a href=\"https://drive.google.com/file/d/1y6JqlIPchkkYjXiZZiZQfR20pOJ0F_Fx/view?usp=share_link\">cx-for-spa.zip</a>&nbsp;</p></li><li><p>Go to installer/recipes folder and extract and paste recipe cx-for-spa under mentioned folder</p></li><li><p>Open CMD inside Installer folder and run the command : install.bat -r cx-for-spa</p></li><li><p>Initialize the system using the following command: install.bat -r cx-for-spa initialize</p></li><li><p>Open CMD inside hybrisinplatform and start your server command : hybrisserver.bat</p></li><li><p>Install Node JS : <a href=\"https://www.npackd.org/p/org.nodejs.NodeJS64/14.17.1\">Node.js 64 bit 14.17.1</a> &nbsp; &nbsp;[version: node-v14.17.1-x64.msi]</p></li><li><p>Create a folder under custom folder name as \"spartacusstore\"</p></li><li><p>Open CMD inside \"spartacusstore\" folder and execute below command:</p><p>npm install --global yarn</p><p>yarn install</p><p>npm install -g @angular/cli@12</p><p>ng new apparel-spa-store --style=scss</p><p>cd apparel-spa-store</p><p>ng add @spartacus/schematics@latest --baseUrl <a href=\"https://localhost:9002/\">https://localhost:9002/</a> --baseSite=apparel-uk-spa --interactive=false</p></li><li><p>Strat your spartacus server with command : yarn start --ssl or ng serve --ssl</p></li><li><p>Navigate to C:WindowsSystem32driversetchosts &nbsp;open hosts file and add the belowproperties and save : 127.0.0.1 &nbsp; localhost electronics.local apparel-uk.local apparel-de.local powertools.local</p></li><li><p>In chrome open -: chrome://flags/#allow-insecure-localhost and enable \"Allow invalid certificates for resources loaded from localhost.\"&nbsp;</p></li><li><p>Open Hac : <a href=\"https://localhost:9002/console/impex/import\">https://localhost:9002/console/impex/impor</a></p><p>Import Below Impex :</p><p>INSERT_UPDATE OAuthClientDetails;clientId[unique=true] &nbsp; &nbsp;;resourceIds &nbsp; &nbsp; &nbsp; ;scope &nbsp; &nbsp; &nbsp; &nbsp;;authorizedGrantTypes &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;authorities &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;clientSecret &nbsp; &nbsp;;registeredRedirectUri</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;client-side &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;hybris &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;basic &nbsp; &nbsp; &nbsp; &nbsp;;implicit,client_credentials &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;ROLE_CLIENT &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;secret &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;<a href=\"http://localhost:9001/authorizationserver/oauth2_implicit_callback%3b\">http://localhost:9001/authorizationserver/oauth2_implicit_callback;</a></p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;mobile_android &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;hybris &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;basic &nbsp; &nbsp; &nbsp; &nbsp;;authorization_code,refresh_token,password,client_credentials &nbsp; &nbsp;;ROLE_CLIENT &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ;secret &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;;<a href=\"http://localhost:9001/authorizationserver/oauth2_callback%3b\">http://localhost:9001/authorizationserver/oauth2_callback;</a></p><p><br></p><p>INSERT_UPDATE CorsConfigurationProperty;key[unique=true];value;context[default=commercewebservices,unique=true]</p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;allowedOrigins;<a href=\"http://localhost:4200/\">http://localhost:4200</a> <a href=\"https://localhost:4200/\">https://localhost:4200</a></p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;allowedOriginPatterns;*</p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;allowedMethods;GET HEAD OPTIONS PATCH PUT POST DELETE</p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;allowedHeaders;origin content-type accept authorization cache-control x-anonymous-consents x-profile-tag-debug x-consent-reference occ-personalization-id occ-personalization-time</p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;allowCredentials;true</p><p>&nbsp; &nbsp; &nbsp; &nbsp; ;exposedHeaders;x-anonymous-consents occ-personalization-id occ-personalization-time</p></li></ol><div contenteditable=\"false\"><hr></div><p><strong>--If Smartedit Login error--</strong></p><p>&nbsp;</p><p>INSERT_UPDATE OAuthClientDetails;clientId[unique=true];resourceIds;scope[mode=append];authorizedGrantTypes;accessTokenValiditySeconds</p><p>&nbsp;;smartedit;hybris;basic,permissionswebservices,previewwebservices;password;3600</p><p>&nbsp;</p><p><strong>---------All Links--------</strong></p><p>HAC -: <a href=\"https://localhost:9002/hac/\">https://localhost:9002/hac/</a></p><p>Backoffice -: <a href=\"https://localhost:9002/backoffice/login.zul\">https://localhost:9002/backoffice/login.zul</a></p><p>SmartEdit -: <a href=\"https://localhost:9002/smartedit/\">https://localhost:9002/smartedit/</a></p><p><a href=\"https://localhost:9002/yacceleratorstorefront/electronics/en/\">https://localhost:9002/yacceleratorstorefront/electronics/en/</a></p><p>Apprel UK Site -: <a href=\"https://apparel-uk.local:9002/yacceleratorstorefront/en/\">https://apparel-uk.local:9002/yacceleratorstorefront/en/</a></p><p>Electronic Site -: <a href=\"https://electronics.local:9002/yacceleratorstorefront/electronics/en/\">https://electronics.local:9002/yacceleratorstorefront/electronics/en/</a></p><p>Powertools Site -: <a href=\"https://powertools.local:9002/yb2bacceleratorstorefront/powertools/en/USD/\">https://powertools.local:9002/yb2bacceleratorstorefront/powertools/en/USD/</a></p><p>Spartacus Site -: <a href=\"https://localhost:4200/\">https://localhost:4200</a></p><p>&nbsp;</p><p><strong>--If java version issue then download jdk zip file and run below command --</strong></p><p>set JAVA_HOME=C:Program FilesJavajdk-17.0.9</p><p>set PATH=%JAVA_HOME%in;%PATH%</p>','2025-01-17 08:30:38','2025-01-20 05:48:02',1,'Share'),(44,'Document1',23,'<p>sfdsf</p><p>sd</p><p>f</p><p>dsf</p><p>s</p><p>df</p><p><br></p>','2025-01-17 09:50:32','2025-01-17 10:04:28',1,'0'),(45,'Document2',23,'<p>sdfsf;,`;</p>','2025-01-17 09:50:32','2025-01-17 09:50:32',1,'0'),(46,'Code Review - SAP Commerce Cloud',23,'<p>ggg</p><p><br></p><table><thead><tr><th colspan=\"1\"><p>Coding Standards for Developing with SAP Commerce Cloud</p></th><th colspan=\"1\"><p><a href=\"https://www.sap.com/cxworks/article/2589634068/coding_standards_for_developing_with_sap_commerce_cloud\">SAP Enterprise Support Academy</a>&nbsp;</p></th></tr></thead><tbody><tr><td colspan=\"1\" rowspan=\"1\"><p>Code Review Checklist</p></td><td colspan=\"1\" rowspan=\"1\"><p><a href=\"https://www.sap.com/cxworks/article/2589632294/example_of_a_code_review_checklist\">SAP Enterprise Support Academy</a>&nbsp;</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Code Quality with Sonar</p></td><td colspan=\"1\" rowspan=\"1\"><p><a href=\"https://www.sap.com/cxworks/article/2589634066/measuring_code_quality_with_sonar\">SAP Enterprise Support Academy</a></p></td></tr></tbody></table><p>&nbsp;</p><h4><strong>How to Use SonarLint checks in local:</strong></h4><p><img src=\"data:image/png;base64,\" contenteditable=\"false\"><br></p><p><a href=\"https://omnireach2021.sharepoint.com/sites/TrainingCenter/SiteAssets/SitePages/Code-Review---SAP-Commerce-Cloud/DevelopmentBestPractices.pdf?web=1\">DevelopmentBestPractices</a></p><p>1</p><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>SonarLint Credentials for Local Developer</code></pre></div><p>2</p><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>http://3.108.123.215:9000/</code></pre></div><p>3</p><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>DEFAULT-HYBRIS: c537917a6c99b3905d8972071330b40fa7ed638a</code></pre></div>','2025-01-17 09:50:32','2025-01-17 10:04:28',1,'Share'),(47,'react-to-pdf',23,'<p>import generatePDF, { Options } from \"react-to-pdf\";</p><p>import { Card } from \"./Card\";</p><p>import { Button } from \"./Button\";</p><p>import { Container } from \"./Container\";</p><p><br></p><p>const options: Options = {</p><p>&nbsp; filename: \"using-function.pdf\",</p><p>&nbsp; page: {</p><p>&nbsp; &nbsp; margin: 20</p><p>&nbsp; }</p><p>};</p><p>const getTargetElement = () =&gt; document.getElementById(\"container\");</p><p><br></p><p>const downloadPdf = () =&gt; generatePDF(getTargetElement, options);</p><p><br></p><p>const App = () =&gt; {</p><p>&nbsp; return (</p><p>&nbsp; &nbsp; &lt;Container&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;Button onClick={downloadPdf}&gt;Download PDF&lt;/Button&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;div id=\"container\"&gt;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &lt;Card imageId={20} title=\"Using function example\" /&gt;</p><p>&nbsp; &nbsp; &nbsp; &lt;/div&gt;</p><p>&nbsp; &nbsp; &lt;/Container&gt;</p><p>&nbsp; );</p><p>};</p><p><br></p><p>export default App;</p><p><br></p><p><br></p>','2025-01-17 10:04:28','2025-01-17 10:04:28',1,'0'),(48,'React Hooks',21,'<h1>Built-in React Hooks</h1><p><em>Hooks</em> let you use different React features from your components. You can either use the built-in Hooks or combine them to build your own. This page lists all built-in Hooks in React.</p><div contenteditable=\"false\"><hr></div><h2>State Hooks</h2><p><em>State</em> lets a component <a href=\"https://react.dev/learn/state-a-components-memory\">“remember” information like user input.</a> For example, a form component can use state to store the input value, while an image gallery component can use state to store the selected image index.</p><p>To add state to a component, use one of these Hooks:</p><ul><li><p><a href=\"https://react.dev/reference/react/useState\"><code>useState</code></a> declares a state variable that you can update directly.</p></li><li><p><a href=\"https://react.dev/reference/react/useReducer\"><code>useReducer</code></a> declares a state variable with the update logic inside a <a href=\"https://react.dev/learn/extracting-state-logic-into-a-reducer\">reducer function.</a></p></li></ul><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>function ImageGallery() {</code></pre></div><p><code>const [index, setIndex] = useState(0);</code></p><p><br></p><p><br></p><p><code>// ...</code></p><div contenteditable=\"false\"><hr></div><h2>Context Hooks </h2><p><em>Context</em> lets a component <a href=\"https://react.dev/learn/passing-props-to-a-component\">receive information from distant parents without passing it as props.</a> For example, your app’s top-level component can pass the current UI theme to all components below, no matter how deep.</p><ul><li><p><a href=\"https://react.dev/reference/react/useContext\"><code>useContext</code></a> reads and subscribes to a context.</p></li></ul><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>function Button() {</code></pre></div><p><code>const theme = useContext(ThemeContext);</code></p><p><br></p><p><br></p><p><code>// ...</code></p><div contenteditable=\"false\"><hr></div><h2>Ref Hooks </h2><p><em>Refs</em> let a component <a href=\"https://react.dev/learn/referencing-values-with-refs\">hold some information that isn’t used for rendering,</a> like a DOM node or a timeout ID. Unlike with state, updating a ref does not re-render your component. Refs are an “escape hatch” from the React paradigm. They are useful when you need to work with non-React systems, such as the built-in browser APIs.</p><ul><li><p><a href=\"https://react.dev/reference/react/useRef\"><code>useRef</code></a> declares a ref. You can hold any value in it, but most often it’s used to hold a DOM node.</p></li><li><p><a href=\"https://react.dev/reference/react/useImperativeHandle\"><code>useImperativeHandle</code></a> lets you customize the ref exposed by your component. This is rarely used.</p></li></ul><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>function Form() {</code></pre></div><p><code>const inputRef = useRef(null);</code></p><p><br></p><p><br></p><p><code>// ...</code></p><div contenteditable=\"false\"><hr></div><h2>Effect Hooks </h2><p><em>Effects</em> let a component <a href=\"https://react.dev/learn/synchronizing-with-effects\">connect to and synchronize with external systems.</a> This includes dealing with network, browser DOM, animations, widgets written using a different UI library, and other non-React code.</p><ul><li><p><a href=\"https://react.dev/reference/react/useEffect\"><code>useEffect</code></a> connects a component to an external system.</p></li></ul><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>function ChatRoom({ roomId }) {</code></pre></div><p><code>useEffect(() =&gt; {</code></p><p><br></p><p><br></p><p><code>const connection = createConnection(roomId);</code></p><p><br></p><p><br></p><p><code>connection.connect();</code></p><p><br></p><p><br></p><p><code>return () =&gt; connection.disconnect();</code></p><p><br></p><p><br></p><p><code>}, [roomId]);</code></p><p><br></p><p><br></p><p><code>// ...</code></p><p>Effects are an “escape hatch” from the React paradigm. Don’t use Effects to orchestrate the data flow of your application. If you’re not interacting with an external system, <a href=\"https://react.dev/learn/you-might-not-need-an-effect\">you might not need an Effect.</a></p><p>There are two rarely used variations of <code>useEffect</code> with differences in timing:</p><ul><li><p><a href=\"https://react.dev/reference/react/useLayoutEffect\"><code>useLayoutEffect</code></a> fires before the browser repaints the screen. You can measure layout here.</p></li><li><p><a href=\"https://react.dev/reference/react/useInsertionEffect\"><code>useInsertionEffect</code></a> fires before React makes changes to the DOM. Libraries can insert dynamic CSS here.</p></li></ul><div contenteditable=\"false\"><hr></div><h2>Performance Hooks </h2><p>A common way to optimize re-rendering performance is to skip unnecessary work. For example, you can tell React to reuse a cached calculation or to skip a re-render if the data has not changed since the previous render.</p><p>To skip calculations and unnecessary re-rendering, use one of these Hooks:</p><ul><li><p><a href=\"https://react.dev/reference/react/useMemo\"><code>useMemo</code></a> lets you cache the result of an expensive calculation.</p></li><li><p><a href=\"https://react.dev/reference/react/useCallback\"><code>useCallback</code></a> lets you cache a function definition before passing it down to an optimized component.</p></li></ul><div data-language=\"text\" class=\"toastui-editor-ww-code-block\"><pre><code>function TodoList({ todos, tab, theme }) {</code></pre></div><p><code>const visibleTodos = useMemo(() =&gt; filterTodos(todos, tab), [todos, tab]);</code></p><p><br></p><p><br></p><p><code>// ...</code></p><p><br></p><p><br></p><p><code>}</code></p><p>Sometimes, you can’t skip re-rendering because the screen actually needs to update. In that case, you can improve performance by separating blocking updates that must be synchronous (like typing into an input) from non-blocking updates which don’t need to block the user interface (like updating a chart).</p><p>To prioritize rendering, use one of these Hooks:</p><ul><li><p><a href=\"https://react.dev/reference/react/useTransition\"><code>useTransition</code></a> lets you mark a state transition as non-blocking and allow other updates to interrupt it.</p></li><li><p><a href=\"https://react.dev/reference/react/useDeferredValue\"><code>useDeferredValue</code></a> lets you defer updating a non-critical part of the UI and let other parts update first.</p></li></ul><div contenteditable=\"false\"><hr></div><h2>Other Hooks </h2><p>These Hooks are mostly useful to library authors and aren’t commonly used in the application code.</p><ul><li><p><a href=\"https://react.dev/reference/react/useDebugValue\"><code>useDebugValue</code></a> lets you customize the label React DevTools displays for your custom Hook.</p></li><li><p><a href=\"https://react.dev/reference/react/useId\"><code>useId</code></a> lets a component associate a unique ID with itself. Typically used with accessibility APIs.</p></li><li><p><a href=\"https://react.dev/reference/react/useSyncExternalStore\"><code>useSyncExternalStore</code></a> lets a component subscribe to an external store.</p></li></ul><ul><li><p><a href=\"https://react.dev/reference/react/useActionState\"><code>useActionState</code></a> allows you to manage state of actions.</p></li></ul><div contenteditable=\"false\"><hr></div><h2>Your own Hooks </h2><p>You can also <a href=\"https://react.dev/learn/reusing-logic-with-custom-hooks#extracting-your-own-custom-hook-from-a-component\">define your own custom Hooks</a> as JavaScript functions.</p>','2025-01-20 05:48:02','2025-01-20 05:48:02',1,'Share'),(49,'Omni DigiLocker',21,'<h2>DigiLocker&nbsp;</h2><p>Login Page</p><p>&nbsp;<img src=\"data:image/png;base64,\" alt=\"image.png\" contenteditable=\"false\"><br></p><p><img src=\"\" contenteditable=\"false\"><br></p><p>Register Page</p><p>&nbsp;</p><p><img src=\"\" contenteditable=\"false\"><br></p><p>&nbsp;</p><p>Documents Page</p><p>&nbsp;</p><p><img src=\"\" contenteditable=\"false\"><br></p><p>&nbsp;</p><p>View Documents Page</p><p>&nbsp;</p><p><img src=\"\" contenteditable=\"false\"><br></p><p>&nbsp;</p><p>Edit Documents Page</p><p>&nbsp;</p><p><img src=\"\" contenteditable=\"false\"><br></p><p>&nbsp;</p><p>Documents Page Options</p><p>&nbsp;</p><p><img src=\"\" contenteditable=\"false\"><br></p><p>&nbsp;</p><p><br></p><p><br></p>','2025-01-28 05:54:22','2025-01-28 05:54:22',1,'0');
